// === Tab: mySketch ===
p5.disableFriendlyErrors = true;

const unit = Math.pow(Math.PI, Math.PI*1.1);
const nums = 800;
let blends;
let colors;
let noiseScale = unit * 30;

let a, b, c, d, e, f;
let group1;
let ac, bc, cc, aColor, bColor, cColor, backColor;
let sizes = [Math.PI / 8, Math.PI / 6, Math.PI / 7];

/////////////////////////////////////////////////////////////////

function setup() {

	blends = [SOFT_LIGHT, DIFFERENCE, BLEND, OVERLAY, SCREEN];

	createCanvas(600, 800);
	backColor = color(rCol());
	background(backColor);
	noStroke();
	let deets = Math.ceil(random(3, 7));
	noiseDetail(deets, 1 / deets * (deets - 1));

	let blend = random(blends);
	blendMode(blend);
	//console.log(blend);

	ac = rCol(62);
	bc = rCol(90);
	cc = rCol(162);

	aColor = color(ac[0], green(backColor), 255 * lerp((blue(backColor)), (bc[1]), 0.5), ac[3]);
	bColor = color(cc[3], green(backColor), 255 * lerp((blue(backColor)), (cc[2]), 0.5), cc[3]);
	cColor = color(cc[0], green(backColor), 255 * lerp((blue(backColor)), (ac[2]), 0.5), cc[3]);

	colors = [ac, bc, cc, aColor, bColor, cColor];

	a = new ParticleGroup(aColor, nums, sizes);
	b = new ParticleGroup(bColor, nums, sizes);
	c = new ParticleGroup(cColor, nums, sizes);
	d = new ParticleGroup(ac, nums, sizes);
	e = new ParticleGroup(bc, nums, sizes);
	f = new ParticleGroup(cc, nums, sizes);

	group1 = [a, b, c, d, e, f];

	for (let group of group1) {
		ParticleGroup.populate(group);

	}

}

/////////////////////////////////////////////////////////////////////////////

function draw() {

	noiseScale += PI * Math.sinh((TAU) * Math.atanh(Math.sin((360 | frameCount + noiseScale) ^ 360)) * ((5 * TAU) * Math.atan(QUARTER_PI / noiseScale)));

	background(0, 0);

	for (let group of group1) {
		group.update();
	}

}

/////////////////////////////////////////////////////////////////////////

class ParticleGroup {

	static populate(aGroup) {
		let amt = aGroup.amount;
		for (let i = 0; i < amt; i++) {
			let newParticle = new Particle(rInc(width, amt / unit), rInc(height, amt / unit), random(aGroup.sizeRange[0] / 2, random(aGroup.sizeRange)));
			aGroup.container.push(newParticle);
		}
	}

	constructor(color, amount, sizeRange) {
		this.color = color;
		this.sizeRange = sizeRange;
		this.amount = amount;
		this.container = [];
		this.populated = false;
	}

	update() {
		for (let particles of this.container) {
			stroke(this.color);
			particles.move();
			particles.checkEdge();
			particles.display();
		}
	}

}

/////////////////////////////////////////////////////////////////////////

class Particle {
	constructor(x, y, size) {
		this.angle = noise((x - width/ 2 )/ noiseScale, (y - height / 2) / noiseScale);
		this.pos = createVector(x, y);
		this.speed = -size * Math.PI;
		this.size = size * PI * 4 / 3;
		this.noiseScale = noiseScale;

	}

	move() {

		this.noiseScale = (noiseScale);
		this.angle = this.noiseScale * noise((this.pos.x - width / 2) / this.noiseScale, (this.pos.y - height / 2) / this.noiseScale);


		this.pos.x += Math.sin(this.angle) * this.speed;
		this.pos.y += Math.cos(this.angle) * this.speed;

	}

	checkEdge() {

		if (this.pos.x < 0) this.pos.x = width - this.size;
		if (this.pos.x > width) this.pos.x = this.size;
		if (this.pos.y < 0) this.pos.y = height - this.size;
		if (this.pos.y > height) this.pos.y = this.size;

	}



	display() {
		strokeWeight(this.size * 1.375);
		point(this.pos.x, this.pos.y);
	}
}

//////////////////////////////////////////////////////////////////////

function rCol(max = 255) {
	return [Math.random() * max, Math.random() * max, Math.random() * max, max];
}

function rInc(input, increment) {
	return Math.round((Math.random() * input) / increment) * increment;
}

function rRange(minimum, maximum) {
	return minimum + Math.random() * (maximum - minimum);
}

//////////////////////////////////////////////////////////////////////////

function doubleClicked() {

	clear();

	var blend = random(blends);

	blendMode(blend);

	//console.log(blend);

	backColor = color(rCol());

	background(backColor);

	noiseSeed(Math.round(Math.random() * 99999));
	noiseScale = unit * 30;
	var deets = Math.ceil(random(3, 7));
	noiseDetail(deets, 1 / deets * (deets - 1));

	ac = rCol(62);
	bc = rCol(90);
	cc = rCol(162);

	aColor = color(ac[0], green(backColor), 255 * lerp((blue(backColor)), (bc[1]), 0.5), ac[3]);
	bColor = color(cc[3], green(backColor), 255 * lerp((blue(backColor)), (cc[2]), 0.5), cc[3]);
	cColor = color(cc[0], green(backColor), 255 * lerp((blue(backColor)), (ac[2]), 0.5), cc[3]);

	colors = [ac, bc, cc, aColor, bColor, cColor];

	a = new ParticleGroup(aColor, nums, sizes);
	b = new ParticleGroup(bColor, nums, sizes);
	c = new ParticleGroup(cColor, nums, sizes);
	d = new ParticleGroup(ac, nums, sizes);
	e = new ParticleGroup(bc, nums, sizes);
	f = new ParticleGroup(cc, nums, sizes);

	for (let group of group1) {

		group.container = [];
		ParticleGroup.populate(group);
		group.color = colors[group1.indexOf(group)];
	}
}

